contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);
        uint ownerBalBefore = address(this).balance;
        uint cBalBefore = address(c).balance;
        bool reverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint ownerBalAfter = address(this).balance;
        uint cBalAfter = address(c).balance;
        assert(
            !reverted
                ? ownerBalAfter == ownerBalBefore + amount && cBalAfter == cBalBefore - amount
                : ownerBalAfter == ownerBalBefore && cBalAfter == cBalBefore
        );
    }

    receive() external payable {}
}

