// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint ownerBalBefore = address(this).balance;
        uint cBalBefore = address(c).balance;
        bool reverted;
        try c.withdraw(amount) { reverted = false; } catch { reverted = true; }
        uint ownerBalAfter = address(this).balance;
        uint cBalAfter = address(c).balance;
        assertTrue(!reverted
                ? ownerBalAfter == ownerBalBefore + amount && cBalAfter == cBalBefore - amount
                : ownerBalAfter == ownerBalBefore && cBalAfter == cBalBefore);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
